fn remove_element(s: &Vec<i32>, k: usize) -> Vec<i32> {
    // We assume k < s.len() as per the problem statement.
    let n = s.len();
    debug_assert!(k < n, "Index k must be less than the length of s");

    // Preallocate a new vector of size n - 1.
    let mut v = Vec::with_capacity(n - 1);

    // Copy all elements before index k.
    v.extend_from_slice(&s[..k]);

    // Copy all elements after index k.
    v.extend_from_slice(&s[k + 1..]);

    v
}

